macro_rules! Channel {
    () => {
        # [doc = " A restricted async-signal-safe channel"] # [doc = ""] # [doc = " This is a bit like the usual channel used for inter-thread communication, but with several"] # [doc = " restrictions:"] # [doc = ""] # [doc = " * There's a limited number of slots (currently 5)."] # [doc = " * There's no way to wait for a place in it or for a value. If value is not available, `None` is"] # [doc = "   returned. If there's no space for a value, the value is silently dropped."] # [doc = ""] # [doc = " In exchange for that, all the operations on that channel are async-signal-safe. That means it"] # [doc = " is possible to use it to communicate between a signal handler and the rest of the world with it"] # [doc = " (specifically, it's designed to send information from the handler to the rest of the"] # [doc = " application). The throwing out of values when full is in line with collating of the same type"] # [doc = " in kernel (you should not use the same channel for multiple different signals)."] # [doc = ""] # [doc = " Technically, this is a MPMC queue which preserves order, but it is expected to be used in MPSC"] # [doc = " mode mostly (in theory, multiple threads can be executing a signal handler for the same signal"] # [doc = " at the same time). The channel is not responsible for wakeups."] # [doc = ""] # [doc = " While the channel is async-signal-safe, you still need to make sure *creating* of the values is"] # [doc = " too (it should not contain anything that allocates, for example ‒ so no `String`s inside, etc)."] # [doc = ""] # [doc = " The code was *not* tuned for performance (signals are not expected to happen often)."] pub struct Channel < T > { storage : [UnsafeCell < Option < T > > ; SLOTS] , empty : AtomicU16 , full : AtomicU16 , }
    };
}

Channel!()